      const sortedPot = [...pot].sort(); let matched = null;
      for (const recipe of MASTER_RECIPES) { const sortedIngredients = [...recipe.ingredients].sort(); if (sortedPot.length === sortedIngredients.length && sortedPot.every((val, idx) => val === sortedIngredients[idx])) { matched = recipe; break; } }
      if (matched) { statusEl.textContent = '✅ Recipe found!'; resultEl.innerHTML = `<span class="text-amber-800 font-bold">${matched.name}</span> — ⭐ ${matched.points} pts, ⏱️ ${matched.time}m`; cookBtn.disabled = false; for (let i = 0; i < 5; i++) { const slot = document.getElementById('cook-slot-' + i); if (slot && G.cookingPot[i]) slot.classList.add('highlight'); } } else { statusEl.textContent = '❌ No recipe matches'; resultEl.innerHTML = '<span class="text-red-500/70">Invalid combination!</span>'; cookBtn.disabled = true; for (let i = 0; i < 5; i++) { const slot = document.getElementById('cook-slot-' + i); if (slot) slot.classList.remove('highlight'); } }
