        const remaining = Math.max(0, total - elapsed); const mins = Math.floor(remaining / 60); const secs = Math.floor(remaining % 60); timerDisplay.textContent = `${mins}:${String(secs).padStart(2, '0')}`; progressContainer.classList.remove('hidden');
