      let html = `<div class="modal-card"><h2 class="text-2xl font-bold text-center" style="background:linear-gradient(135deg,#7ad07a,#4a9a4a,#2d7a2d);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">⏱️ Plant Growing Times</h2><div class="max-h-96 overflow-y-auto mt-4"><table class="w-full text-sm"><thead><tr><th class="text-left p-1 text-amber-700/60">Plant</th><th class="text-left p-1 text-amber-700/60">Rarity</th><th class="text-center p-1 text-amber-700/60">Time (s)</th><th class="text-center p-1 text-amber-700/60">Value</th></tr></thead><tbody>`;
      const rarities = ['common', 'rare', 'mythic', 'divine', 'prismatic', 'exotic', 'iridescent'];
      for (const r of rarities) { for (const p of PLANT_DEFS[r] || []) { const rc = getRarityClass(r); html += `<tr><td>${p.name}</td><td><span class="rarity-badge ${rc}">${r}</span></td><td class="text-center">${p.growTime}</td><td class="text-center">$${formatMoney(p.value)}</td></tr>`; } }
      html += `</tbody></table></div><button class="close-modal-btn vine-btn" style="background:linear-gradient(145deg,#3a5a3a,#2a4a2a);">Close</button></div>`;
