      for (const [key, data] of Object.entries(G.inventory)) { if (GEAR_SHOP[data.item]) continue; if (data.item === '🍳 Gourmet Egg') continue; if (data.item.includes('Seed')) continue; if (data.quantity > 0) { let value = 0; const def = findPlant(data.item); if (def) { value = def.value; for (const m of data.mutations || []) value *= getMutationMult(m); if (G.pets.active.includes('cat')) value *= 2; if (G.ascension.sellBonus > 0) value *= (1 + G.ascension.sellBonus / 100) * (1 + getRebUp('sellMulti')); } totalValue += value * data.quantity; toRemove.push(key); } }
